using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;
using System.Web;
using System.Text;
using System.Text.RegularExpressions;

namespace BackgroundWorker
{
    public class NotificationTemplate
    {
        public string Id { get; set; }
        public string HtmlBody { get; set; }
        public bool IsPreSanitized { get; set; }
    }

    public class UserNotification
    {
        public string UserId { get; set; }
        public string TemplateId { get; set; }
        public ConcurrentDictionary<string, string> Parameters { get; set; }
        public DateTime QueuedAt { get; set; }
    }

    public interface INotificationSink
    {
        Task DeliverAsync(string userId, string renderedHtml);
    }

    public class HtmlSanitizer
    {
        private static readonly Regex ScriptPattern = new Regex(
            @"<script[^>]*>.*?</script>", RegexOptions.IgnoreCase | RegexOptions.Singleline);
        private static readonly Regex EventHandlerPattern = new Regex(
            @"\bon\w+\s*=", RegexOptions.IgnoreCase);

        public static string Sanitize(string input)
        {
            if (string.IsNullOrEmpty(input)) return input;
            var result = ScriptPattern.Replace(input, "");
            result = EventHandlerPattern.Replace(result, "");
            return result;
        }

        public static string EncodeForHtmlAttribute(string input)
        {
            return HttpUtility.HtmlAttributeEncode(input);
        }

        public static string EncodeForHtmlContent(string input)
        {
            return HttpUtility.HtmlEncode(input);
        }
    }

    public class TemplateRenderer
    {
        private readonly ConcurrentDictionary<string, NotificationTemplate> _templateCache;
        private readonly SemaphoreSlim _renderLock = new SemaphoreSlim(1, 1);
        private StringBuilder _sharedBuffer;

        public TemplateRenderer()
        {
            _templateCache = new ConcurrentDictionary<string, NotificationTemplate>();
            _sharedBuffer = new StringBuilder(4096);
            SeedTemplates();
        }

        private void SeedTemplates()
        {
            _templateCache["welcome"] = new NotificationTemplate
            {
                Id = "welcome",
                HtmlBody = "<div class='notification'><h2>Welcome, {{username}}!</h2><p>{{message}}</p></div>",
                IsPreSanitized = false
            };
            _templateCache["alert"] = new NotificationTemplate
            {
                Id = "alert",
                HtmlBody = "<div class='alert'><strong>{{title}}</strong><span>{{body}}</span></div>",
                IsPreSanitized = false
            };
            _templateCache["system"] = new NotificationTemplate
            {
                Id = "system",
                HtmlBody = "<div class='system-msg'>{{content}}</div>",
                IsPreSanitized = true
            };
        }

        public async Task<string> RenderAsync(UserNotification notification)
        {
            if (!_templateCache.TryGetValue(notification.TemplateId, out var template))
                throw new ArgumentException($"Template '{notification.TemplateId}' not found");

            await _renderLock.WaitAsync();
            try
            {
                _sharedBuffer.Clear();
                _sharedBuffer.Append(template.HtmlBody);

                foreach (var param in notification.Parameters)
                {
                    var placeholder = "{{" + param.Key + "}}";
                    var safeValue = ResolveParameterValue(param.Value, template.IsPreSanitized);
                    _sharedBuffer.Replace(placeholder, safeValue);
                }

                return _sharedBuffer.ToString();
            }
            finally
            {
                _renderLock.Release();
            }
        }

        private string ResolveParameterValue(string rawValue, bool templateIsPreSanitized)
        {
            // Always encode user-supplied values regardless of template trust level
            return HtmlSanitizer.EncodeForHtmlContent(rawValue);
        }
    }

    public class NotificationWorker
    {
        private readonly ConcurrentQueue<UserNotification> _queue;
        private readonly TemplateRenderer _renderer;
        private readonly INotificationSink _sink;
        private readonly CancellationTokenSource _cts;
        private readonly int _maxConcurrency;
        private static readonly HashSet<string> _allowedTemplateIds = new HashSet<string> { "welcome", "alert", "system" };

        public NotificationWorker(INotificationSink sink, int maxConcurrency = 4)
        {
            _queue = new ConcurrentQueue<UserNotification>();
            _renderer = new TemplateRenderer();
            _sink = sink;
            _cts = new CancellationTokenSource();
            _maxConcurrency = maxConcurrency;
        }

        public void Enqueue(UserNotification notification)
        {
            if (notification == null) throw new ArgumentNullException(nameof(notification));
            if (string.IsNullOrEmpty(notification.TemplateId))
                throw new ArgumentException("TemplateId is required");
            if (!_allowedTemplateIds.Contains(notification.TemplateId))
                throw new ArgumentException("Invalid TemplateId");
            notification.QueuedAt = DateTime.UtcNow;
            _queue.Enqueue(notification);
        }

        public async Task ProcessBatchAsync()
        {
            var tasks = new Task[_maxConcurrency];
            for (int i = 0; i < _maxConcurrency; i++)
            {
                tasks[i] = ProcessSingleAsync();
            }
            await Task.WhenAll(tasks);
        }

        private async Task ProcessSingleAsync()
        {
            while (_queue.TryDequeue(out var notification))
            {
                if (_cts.Token.IsCancellationRequested) break;

                try
                {
                    var html = await _renderer.RenderAsync(notification);
                    await _sink.DeliverAsync(notification.UserId, html);
                }
                catch (Exception ex)
                {
                    await HandleErrorAsync(notification, ex);
                }
            }
        }

        private Task HandleErrorAsync(UserNotification notification, Exception ex)
        {
            // Log error without including user-controlled data in output
            Console.Error.WriteLine($"Failed to process notification for user: {ex.GetType().Name}");
            return Task.CompletedTask;
        }

        public void Stop() => _cts.Cancel();
    }
}
